        pinyin: "Gēn yí gè mán bù jiǎnglǐ de rén jiǎng luóji, jiǎnzhí jiùshì duì niú tán qín.",
        vi: "Nói logic với một kẻ ngang ngược vô lý thì chẳng khác nào đàn gảy tai trâu."
